/*
 * Interactive changelog explorer.
 *
 * Drives the widget on documentation/changelog/index.md. Every release Scalar has
 * published across its four products is merged into one stream you can filter,
 * search, scrub by week, and diff between two versions.
 *
 * The page ships a complete static view of the same links, so it still reads
 * correctly without JavaScript; everything below is progressive enhancement that
 * replaces that view once the data file has loaded.
 *
 * Release data comes from `documentation/assets/changelog-data.js`, generated by
 * `pnpm script generate-changelog-data`.
 */

/** Remembers where a reader left off, so returning shows what is new since then. */
const LAST_VISIT_KEY = 'scalar-changelog-last-visit'

/** Below this many weeks the activity chart buckets by week, above it by month. */
const WEEKLY_BUCKET_LIMIT = 30

const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

const DAY_IN_MS = 24 * 60 * 60 * 1000

const prefersReducedMotion = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

const qs = (root, selector) => root.querySelector(selector)

const escapeHtml = (value) =>
  String(value).replace(
    /[&<>"']/g,
    (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character],
  )

/** Escape for HTML, then wrap every match of `query` in a `mark`. */
const highlight = (value, query) => {
  const escaped = escapeHtml(value)
  if (!query) {
    return escaped
  }
  const pattern = new RegExp(escapeHtml(query).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi')
  return escaped.replace(pattern, (match) => `<mark>${match}</mark>`)
}

/** Parse an ISO `YYYY-MM-DD` date at UTC midnight, so no timezone can shift the day. */
const parseDate = (iso) => {
  const [year, month, day] = iso.split('-').map(Number)
  return new Date(Date.UTC(year, month - 1, day))
}

const todayUtc = () => {
  const now = new Date()
  return new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()))
}

const toIsoDate = (date) => date.toISOString().slice(0, 10)

const formatDate = (date) => `${MONTH_NAMES[date.getUTCMonth()]} ${date.getUTCDate()}, ${date.getUTCFullYear()}`

const relativeFormatter = new Intl.RelativeTimeFormat('en', { numeric: 'auto' })

/** "yesterday", "3 weeks ago", "2 months ago" - whichever unit reads best. */
const formatRelative = (date, reference) => {
  const days = Math.round((date.getTime() - reference.getTime()) / DAY_IN_MS)

  if (Math.abs(days) < 1) {
    return 'today'
  }
  if (Math.abs(days) < 7) {
    return relativeFormatter.format(days, 'day')
  }
  if (Math.abs(days) < 30) {
    return relativeFormatter.format(Math.round(days / 7), 'week')
  }
  if (Math.abs(days) < 365) {
    return relativeFormatter.format(Math.round(days / 30), 'month')
  }
  return relativeFormatter.format(Math.round(days / 365), 'year')
}

const pluralize = (count, singular, plural) => `${count} ${count === 1 ? singular : (plural ?? `${singular}s`)}`

/** An id that is safe in both a URL fragment and a CSS selector. */
const releaseId = (release) => `${release.product}-${release.version.replace(/\./g, '-')}`

/** The Monday of the week a date falls in, in UTC. */
const startOfWeek = (date) => {
  const result = new Date(date.getTime())
  // getUTCDay is 0 on Sunday, which belongs to the week that started six days earlier.
  const offset = (result.getUTCDay() + 6) % 7
  result.setUTCDate(result.getUTCDate() - offset)
  return result
}

const startOfMonth = (date) => new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1))

const compareVersions = (a, b) => {
  const left = a.split(/[-+]/)[0].split('.').map(Number)
  const right = b.split(/[-+]/)[0].split('.').map(Number)

  for (let index = 0; index < 3; index++) {
    const difference = (left[index] || 0) - (right[index] || 0)
    if (difference !== 0) {
      return difference
    }
  }
  return 0
}

// ---------------------------------------------------------------------------
// Stored last visit
// ---------------------------------------------------------------------------

/*
 * Reading and writing can both throw when a browser blocks site data, so every
 * access is guarded and the explorer simply shows nothing as new in that case.
 */
const readLastVisit = () => {
  try {
    const stored = window.localStorage.getItem(LAST_VISIT_KEY)
    return stored && /^\d{4}-\d{2}-\d{2}$/.test(stored) ? stored : null
  } catch {
    return null
  }
}

const writeLastVisit = (iso) => {
  try {
    window.localStorage.setItem(LAST_VISIT_KEY, iso)
  } catch {
    // A reader who blocks storage just never sees the "new since" badges.
  }
}

// ---------------------------------------------------------------------------
// Activity chart
// ---------------------------------------------------------------------------

/**
 * Bucket releases into evenly spaced columns covering the published range.
 *
 * Short histories read better week by week; once a project has shipped for long
 * enough that weekly columns would not fit, the same chart switches to months.
 */
const buildBuckets = (releases) => {
  if (releases.length === 0) {
    return { unit: 'week', buckets: [] }
  }

  const dates = releases.map((release) => parseDate(release.date))
  const first = new Date(Math.min(...dates.map((date) => date.getTime())))
  const last = new Date(Math.max(...dates.map((date) => date.getTime())))

  const weekSpan = Math.round((startOfWeek(last) - startOfWeek(first)) / (7 * DAY_IN_MS)) + 1
  const unit = weekSpan <= WEEKLY_BUCKET_LIMIT ? 'week' : 'month'

  const buckets = []
  const cursor = unit === 'week' ? startOfWeek(first) : startOfMonth(first)
  const end = unit === 'week' ? startOfWeek(last) : startOfMonth(last)

  while (cursor <= end) {
    const start = new Date(cursor.getTime())
    const next =
      unit === 'week'
        ? new Date(start.getTime() + 7 * DAY_IN_MS)
        : new Date(Date.UTC(start.getUTCFullYear(), start.getUTCMonth() + 1, 1))

    buckets.push({
      start,
      end: new Date(next.getTime() - DAY_IN_MS),
      key: toIsoDate(start),
      releases: releases.filter((release) => {
        const date = parseDate(release.date)
        return date >= start && date < next
      }),
    })

    cursor.setTime(next.getTime())
  }

  return { unit, buckets }
}

const bucketLabel = (bucket, unit) =>
  unit === 'week'
    ? `Week of ${formatDate(bucket.start)}`
    : `${MONTH_NAMES[bucket.start.getUTCMonth()]} ${bucket.start.getUTCFullYear()}`

// ---------------------------------------------------------------------------
// The explorer
// ---------------------------------------------------------------------------

const initChangelog = (root) => {
  if (root.dataset.changelogReady === 'true') {
    return
  }

  const data = window.scalarChangelog

  // Without the data file there is nothing to enhance, so leave the static view.
  if (!data || !Array.isArray(data.releases) || data.releases.length === 0) {
    return
  }

  root.dataset.changelogReady = 'true'

  const products = data.products
  const productBySlug = new Map(products.map((product) => [product.slug, product]))
  const releases = data.releases.filter((release) => productBySlug.has(release.product))

  const nodes = {
    stats: qs(root, '[data-changelog-stats]'),
    chart: qs(root, '[data-changelog-chart]'),
    chartLegend: qs(root, '[data-changelog-chart-legend]'),
    chartReset: qs(root, '[data-changelog-chart-reset]'),
    chips: qs(root, '[data-changelog-chips]'),
    search: qs(root, '[data-changelog-search]'),
    features: qs(root, '[data-changelog-features]'),
    compareToggle: qs(root, '[data-changelog-compare]'),
    comparePanel: qs(root, '[data-changelog-compare-panel]'),
    compareProduct: qs(root, '[data-changelog-compare-product]'),
    compareFrom: qs(root, '[data-changelog-compare-from]'),
    compareTo: qs(root, '[data-changelog-compare-to]'),
    compareSummary: qs(root, '[data-changelog-compare-summary]'),
    count: qs(root, '[data-changelog-count]'),
    stream: qs(root, '[data-changelog-stream]'),
    empty: qs(root, '[data-changelog-empty]'),
    reset: qs(root, '[data-changelog-reset]'),
    markRead: qs(root, '[data-changelog-mark-read]'),
  }

  const today = todayUtc()

  /*
   * The stamp is written straight away and the previous value kept in memory, so
   * the badges stay put while this page is being read and are gone on the next
   * visit - which is what "since you were last here" should mean.
   */
  const lastVisit = readLastVisit()
  writeLastVisit(toIsoDate(today))

  /* Flipped by "Mark read" so the badges stay gone through later renders. */
  let newDismissed = false

  const isNew = (release) => !newDismissed && lastVisit !== null && release.date > lastVisit
  const newCount = releases.filter(isNew).length

  const { unit, buckets } = buildBuckets(releases)

  const state = {
    /** Empty means every product. */
    productFilter: new Set(),
    query: '',
    featuresOnly: false,
    /** The key of the selected activity bucket, or null for the whole history. */
    bucket: null,
    compare: null,
    expanded: new Set(),
  }

  // -------------------------------------------------------------------------
  // Filtering
  // -------------------------------------------------------------------------

  const matchesQuery = (release, query) => {
    if (!query) {
      return true
    }
    const haystack = [release.title, release.summary, release.version, productBySlug.get(release.product).name]
      .concat(release.highlights)
      .join('\n')
      .toLowerCase()
    return haystack.includes(query)
  }

  const visibleReleases = () => {
    if (state.compare) {
      const { product, from, to } = state.compare
      return releases.filter(
        (release) =>
          release.product === product &&
          compareVersions(release.version, from) > 0 &&
          compareVersions(release.version, to) <= 0,
      )
    }

    const query = state.query.trim().toLowerCase()
    const bucket = state.bucket ? buckets.find((candidate) => candidate.key === state.bucket) : null

    return releases.filter((release) => {
      if (state.productFilter.size > 0 && !state.productFilter.has(release.product)) {
        return false
      }
      if (state.featuresOnly && release.kind === 'patch') {
        return false
      }
      if (bucket && !bucket.releases.includes(release)) {
        return false
      }
      return matchesQuery(release, query)
    })
  }

  const hasActiveFilter = () =>
    state.productFilter.size > 0 || state.query.trim() !== '' || state.featuresOnly || state.bucket !== null

  // -------------------------------------------------------------------------
  // Rendering
  // -------------------------------------------------------------------------

  const renderStats = () => {
    const latest = parseDate(releases[0].date)
    const highlightCount = releases.reduce((total, release) => total + release.highlights.length, 0)

    const tiles = [
      { value: String(releases.length), label: 'releases published' },
      { value: String(highlightCount), label: 'changes shipped' },
      { value: String(products.length), label: 'products tracked' },
      { value: formatRelative(latest, today), label: 'last shipped', title: formatDate(latest) },
    ]

    nodes.stats.innerHTML = tiles
      .map(
        (tile) => `
        <div class="changelog-stat"${tile.title ? ` title="${escapeHtml(tile.title)}"` : ''}>
          <span class="changelog-stat-value">${escapeHtml(tile.value)}</span>
          <span class="changelog-stat-label">${escapeHtml(tile.label)}</span>
        </div>`,
      )
      .join('')

    if (nodes.markRead) {
      nodes.markRead.hidden = newDismissed || newCount === 0
      nodes.markRead.querySelector('[data-changelog-new-count]').textContent = pluralize(newCount, 'new release')
    }
  }

  const renderChart = () => {
    const tallest = Math.max(1, ...buckets.map((bucket) => bucket.releases.length))

    nodes.chart.innerHTML = buckets
      .map((bucket) => {
        const total = bucket.releases.length
        const isSelected = state.bucket === bucket.key
        const label = bucketLabel(bucket, unit)
        const summary = total === 0 ? 'no releases' : pluralize(total, 'release')

        // Each product gets its own slice of the column, tallest bucket fills it.
        const segments = products
          .map((product) => {
            const count = bucket.releases.filter((release) => release.product === product.slug).length
            if (count === 0) {
              return ''
            }
            return `<span class="changelog-chart-segment" data-product="${product.slug}" style="flex-grow:${count}" title="${escapeHtml(`${product.name}: ${pluralize(count, 'release')}`)}"></span>`
          })
          .join('')

        return `
        <button
          class="changelog-chart-column"
          type="button"
          data-changelog-bucket="${bucket.key}"
          aria-pressed="${isSelected}"
          title="${escapeHtml(`${label} — ${summary}`)}">
          <span class="changelog-chart-bar" style="height:${total === 0 ? 2 : Math.round((total / tallest) * 100)}%">${segments}</span>
          <span class="changelog-chart-tick">${escapeHtml(
            unit === 'week' ? `${bucket.start.getUTCDate()}` : MONTH_NAMES[bucket.start.getUTCMonth()].slice(0, 1),
          )}</span>
        </button>`
      })
      .join('')

    if (nodes.chartReset) {
      nodes.chartReset.hidden = state.bucket === null
    }
  }

  const renderLegend = () => {
    nodes.chartLegend.innerHTML = products
      .map(
        (product) => `
        <span class="changelog-legend-item">
          <span class="changelog-legend-swatch" data-product="${product.slug}"></span>
          ${escapeHtml(product.name)}
        </span>`,
      )
      .join('')
  }

  const renderChips = () => {
    const chips = products.map((product) => {
      const count = releases.filter((release) => release.product === product.slug).length
      const active = state.productFilter.has(product.slug)
      return `
        <button
          class="changelog-chip"
          type="button"
          data-product="${product.slug}"
          data-changelog-chip="${product.slug}"
          aria-pressed="${active}">
          <span class="changelog-chip-dot"></span>
          ${escapeHtml(product.name)}
          <span class="changelog-chip-count">${count}</span>
        </button>`
    })

    nodes.chips.innerHTML = `
      <button class="changelog-chip changelog-chip-all" type="button" data-changelog-chip="" aria-pressed="${state.productFilter.size === 0}">
        All products
        <span class="changelog-chip-count">${releases.length}</span>
      </button>${chips.join('')}`
  }

  const renderCompareOptions = () => {
    const product = nodes.compareProduct.value
    const versions = releases
      .filter((release) => release.product === product)
      .map((release) => release.version)
      .sort((a, b) => compareVersions(b, a))

    // "from" is exclusive, so the oldest version can be a starting point but never
    // a destination, and the newest is the reverse.
    const options = (list, selected) =>
      list
        .map(
          (version) =>
            `<option value="${escapeHtml(version)}"${version === selected ? ' selected' : ''}>${escapeHtml(version)}</option>`,
        )
        .join('')

    const fromChoices = versions.slice(1)
    const toChoices = versions.slice(0, -1)

    nodes.compareFrom.innerHTML = options(fromChoices, fromChoices[Math.min(2, fromChoices.length - 1)])
    nodes.compareTo.innerHTML = options(toChoices, toChoices[0])
  }

  const applyCompare = () => {
    const product = nodes.compareProduct.value
    let from = nodes.compareFrom.value
    let to = nodes.compareTo.value

    // Reading the range backwards is an easy slip; treat it as the same range.
    if (compareVersions(from, to) > 0) {
      ;[from, to] = [to, from]
    }

    state.compare = { product, from, to }
    render()
  }

  const renderCompareSummary = (matched) => {
    if (!state.compare) {
      nodes.compareSummary.textContent = ''
      return
    }

    const product = productBySlug.get(state.compare.product)
    const changes = matched.reduce((total, release) => total + release.highlights.length, 0)

    nodes.compareSummary.innerHTML =
      matched.length === 0
        ? `Nothing landed in ${escapeHtml(product.name)} between <code>${escapeHtml(state.compare.from)}</code> and <code>${escapeHtml(state.compare.to)}</code>.`
        : `Upgrading ${escapeHtml(product.name)} from <code>${escapeHtml(state.compare.from)}</code> to <code>${escapeHtml(state.compare.to)}</code> brings <strong>${pluralize(matched.length, 'release')}</strong> and <strong>${pluralize(changes, 'change')}</strong>.`
  }

  const renderCard = (release, index, query) => {
    const product = productBySlug.get(release.product)
    const date = parseDate(release.date)
    const id = releaseId(release)
    const expanded = state.expanded.has(id) || Boolean(state.compare)
    const fresh = isNew(release)

    const highlights = release.highlights.map((item) => `<li>${highlight(item, query)}</li>`).join('')

    return `
      <li
        class="changelog-entry"
        id="${id}"
        data-product="${release.product}"
        data-kind="${release.kind}"
        data-new="${fresh}"
        style="--changelog-entry-index:${index}">
        <div class="changelog-entry-rail" aria-hidden="true">
          <span class="changelog-entry-dot"></span>
        </div>
        <div class="changelog-entry-aside">
          <time class="changelog-entry-date" datetime="${release.date}">${escapeHtml(formatDate(date))}</time>
          <span class="changelog-entry-ago">${escapeHtml(formatRelative(date, today))}</span>
        </div>
        <article class="changelog-card">
          <header class="changelog-card-head">
            <span class="changelog-badge">
              <span class="changelog-badge-dot"></span>
              ${escapeHtml(product.name)}
            </span>
            <code class="changelog-version">${highlight(release.version, query)}</code>
            <span class="changelog-kind">${escapeHtml(release.kind)}</span>
            ${fresh ? '<span class="changelog-new">New</span>' : ''}
            <a class="changelog-permalink" href="#${id}" aria-label="Link to this release">#</a>
          </header>
          <h3 class="changelog-card-title">${highlight(release.title, query)}</h3>
          ${release.summary ? `<p class="changelog-card-summary">${highlight(release.summary, query)}</p>` : ''}
          ${
            highlights
              ? `
          <button
            class="changelog-card-toggle"
            type="button"
            data-changelog-toggle="${id}"
            aria-expanded="${expanded}"
            aria-controls="${id}-changes">
            <span class="changelog-card-caret" aria-hidden="true">▸</span>
            ${escapeHtml(pluralize(release.highlights.length, 'change'))}
          </button>
          <ul class="changelog-card-changes" id="${id}-changes"${expanded ? '' : ' hidden'}>${highlights}</ul>`
              : ''
          }
          ${
            release.href
              ? `<a class="changelog-card-link" href="${escapeHtml(release.href)}" target="_blank" rel="noreferrer">Full changelog on GitHub →</a>`
              : ''
          }
        </article>
      </li>`
  }

  const render = () => {
    const matched = visibleReleases()
    const query = state.compare ? '' : state.query.trim().toLowerCase()

    renderChips()
    renderChart()
    renderCompareSummary(matched)

    nodes.comparePanel.hidden = !state.compare
    nodes.compareToggle.setAttribute('aria-expanded', String(Boolean(state.compare)))
    nodes.features.setAttribute('aria-pressed', String(state.featuresOnly))

    nodes.stream.innerHTML = matched.map((release, index) => renderCard(release, index, query)).join('')
    nodes.stream.dataset.animate = prefersReducedMotion() ? 'false' : 'true'

    nodes.empty.hidden = matched.length > 0
    nodes.count.textContent = state.compare
      ? ''
      : matched.length === releases.length
        ? `Showing all ${pluralize(releases.length, 'release')}`
        : `Showing ${matched.length} of ${pluralize(releases.length, 'release')}`

    if (nodes.reset) {
      nodes.reset.hidden = !hasActiveFilter() && !state.compare
    }
  }

  // -------------------------------------------------------------------------
  // Interaction
  // -------------------------------------------------------------------------

  const clearFilters = () => {
    state.productFilter.clear()
    state.query = ''
    state.featuresOnly = false
    state.bucket = null
    state.compare = null
    nodes.search.value = ''
    render()
  }

  nodes.chips.addEventListener('click', (event) => {
    const chip = event.target.closest('[data-changelog-chip]')
    if (!chip) {
      return
    }

    const slug = chip.dataset.changelogChip
    state.compare = null

    if (!slug) {
      state.productFilter.clear()
    } else if (state.productFilter.has(slug)) {
      state.productFilter.delete(slug)
    } else {
      state.productFilter.add(slug)
    }

    render()
  })

  nodes.chart.addEventListener('click', (event) => {
    const column = event.target.closest('[data-changelog-bucket]')
    if (!column) {
      return
    }
    const key = column.dataset.changelogBucket
    state.compare = null
    state.bucket = state.bucket === key ? null : key
    render()
  })

  nodes.chartReset?.addEventListener('click', () => {
    state.bucket = null
    render()
  })

  nodes.search.addEventListener('input', () => {
    state.query = nodes.search.value
    state.compare = null
    render()
  })

  nodes.features.addEventListener('click', () => {
    state.featuresOnly = !state.featuresOnly
    state.compare = null
    render()
  })

  nodes.compareToggle.addEventListener('click', () => {
    if (state.compare) {
      state.compare = null
      render()
      return
    }
    renderCompareOptions()
    applyCompare()
    nodes.comparePanel.hidden = false
    nodes.compareProduct.focus()
  })

  nodes.compareProduct.addEventListener('change', () => {
    renderCompareOptions()
    applyCompare()
  })

  nodes.compareFrom.addEventListener('change', applyCompare)
  nodes.compareTo.addEventListener('change', applyCompare)

  nodes.reset?.addEventListener('click', clearFilters)

  nodes.markRead?.addEventListener('click', () => {
    newDismissed = true
    renderStats()
    render()
  })

  /* Expanding a card is the one interaction that must not re-render the stream,
   * or the click would scroll out from under the reader. */
  nodes.stream.addEventListener('click', (event) => {
    const toggle = event.target.closest('[data-changelog-toggle]')
    if (!toggle) {
      return
    }

    const id = toggle.dataset.changelogToggle
    const list = root.querySelector(`#${CSS.escape(`${id}-changes`)}`)
    const next = !state.expanded.has(id)

    if (next) {
      state.expanded.add(id)
    } else {
      state.expanded.delete(id)
    }

    toggle.setAttribute('aria-expanded', String(next))
    list.hidden = !next
  })

  document.addEventListener('keydown', (event) => {
    const typing = /^(INPUT|TEXTAREA|SELECT)$/.test(event.target.tagName) || event.target.isContentEditable

    if (event.key === '/' && !typing && !event.metaKey && !event.ctrlKey) {
      event.preventDefault()
      nodes.search.focus()
      nodes.search.select()
      return
    }

    if (event.key === 'Escape' && (typing ? event.target === nodes.search : true)) {
      if (state.compare || hasActiveFilter()) {
        clearFilters()
        nodes.search.blur()
      }
      return
    }

    if (typing || event.metaKey || event.ctrlKey || event.altKey) {
      return
    }

    // j and k walk the stream the way they walk a list of mail.
    if (event.key !== 'j' && event.key !== 'k') {
      return
    }

    const entries = [...nodes.stream.querySelectorAll('.changelog-entry')]
    if (entries.length === 0) {
      return
    }

    event.preventDefault()
    const current = entries.findIndex((entry) => entry.contains(document.activeElement))
    const offset = event.key === 'j' ? 1 : -1
    const next = entries[Math.min(entries.length - 1, Math.max(0, (current === -1 ? -offset : current) + offset))]

    const focusTarget = next.querySelector('[data-changelog-toggle]') ?? next.querySelector('.changelog-permalink')
    focusTarget?.focus({ preventScroll: true })
    next.scrollIntoView({ block: 'center', behavior: prefersReducedMotion() ? 'auto' : 'smooth' })
  })

  // -------------------------------------------------------------------------
  // Boot
  // -------------------------------------------------------------------------

  nodes.compareProduct.innerHTML = products
    .map((product) => `<option value="${product.slug}">${escapeHtml(product.name)}</option>`)
    .join('')

  renderLegend()
  renderStats()
  render()

  // The static list only exists for readers without JavaScript.
  root.querySelectorAll('[data-changelog-static]').forEach((node) => {
    node.hidden = true
  })
  root.dataset.changelogState = 'live'

  /* A link to a specific release has to survive landing on a filtered view, so
   * open the card it points at and bring it into view. */
  const openHashTarget = () => {
    const hash = window.location.hash.slice(1)
    if (!hash || !root.querySelector(`#${CSS.escape(hash)}`)) {
      return
    }
    state.expanded.add(hash)
    render()
    root.querySelector(`#${CSS.escape(hash)}`)?.scrollIntoView({ block: 'center' })
  }

  // Following a permalink from inside the page never reloads the script.
  window.addEventListener('hashchange', openHashTarget)

  openHashTarget()
}

const initAll = () => {
  document.querySelectorAll('[data-changelog]').forEach(initChangelog)
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => initAll(), { once: true })
} else {
  initAll()
}

/* The two scripts are loaded independently, so the data file may land after this
 * one has already given up on finding it. */
document.addEventListener('scalar-changelog-data', () => initAll())

/* Docs pages swap their content client side, so re-run when the widget lands. */
const changelogObserver = new MutationObserver((records) => {
  if (!records.some((record) => record.addedNodes.length)) {
    return
  }
  initAll()
})

changelogObserver.observe(document.documentElement || document.body, {
  childList: true,
  subtree: true,
})
